function playTone(freq,duration,type='sine'){try{audioCtx ||=new(window.AudioContext||window.webkitAudioContext)();let o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type=type;o.frequency.value=freq;g.gain.setValueAtTime(.035,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+duration)}catch(e){}}
function backButton(){return '<button class="back" data-back>← &nbsp; MENU PRINCIPALE</button>'}
function showPage(name){let html='';if(name==='kickoff'){html=`${backButton()}<div class="eyebrow">Matchday · Amichevole</div><h2 class="page-title">Scegli le squadre</h2><div class="team-grid"><div class="team-card"><div class="team-head"><div class="team-logo">N</div><div><div class="team-name">NFG United</div><div class="team-meta">Casa · OVR 84 · 4-3-3</div></div></div><div class="kit-row">MAGLIA ${["#d7ff32","#18c397","#f4f4e8","#df5848"].map((c,i)=>`<span class="swatch ${i===0?'active':''}" data-team="0" style="background:${c}"></span>`).join('')}</div></div><div class="team-card away"><div class="team-head"><div class="team-logo">V</div><div><div class="team-name">Valley Rovers</div><div class="team-meta">Ospiti · OVR 81 · 4-4-2</div></div></div><div class="kit-row">MAGLIA ${["#e85547","#3268df","#f4f4e8","#20252a"].map((c,i)=>`<span class="swatch ${i===0?'active':''}" data-team="1" style="background:${c}"></span>`).join('')}</div></div></div><div class="info-row">◷ &nbsp; 2 minuti · Difficoltà accessibile · Stadio Aurora</div><button class="primary-btn" data-start>Scendi in campo &nbsp; →</button>`}
else if(name==='coach'){html=`${backButton()}<div class="eyebrow">Il tuo club · Stagione 2027</div><h2 class="page-title">Modalità Allenatore</h2><div class="coach-grid"><div class="card-panel"><div class="eyebrow">Forma squadra · Ultime 6 gare</div><div class="chart">${[52,67,48,82,73,91].map((n,i)=>`<div class="bar" style="height:${n}%"><span>${i+1}</span></div>`).join('')}</div><div class="stat-row"><span>Record</span><b>W W P W V W</b></div><div class="stat-row"><span>Posizione lega</span><b>3° / 18</b></div><div class="stat-row"><span>Budget trasferimenti</span><b>€ 42,5M</b></div></div><div class="card-panel"><div class="eyebrow">Formazione · 4-3-3</div><div class="formation"><span class="dot">GK</span><span class="dot">DIF</span><span class="dot">DIF</span><span class="dot">CEN</span><span class="dot">ATT</span></div><div class="stat-row"><span>Attacco</span><b>84</b></div><div class="stat-row"><span>Centrocampo</span><b>81</b></div><div class="stat-row"><span>Difesa</span><b>79</b></div><button class="secondary-btn" data-form>Gestisci formazione</button></div><div class="card-panel" style="grid-column:1/-1"><div class="eyebrow">Mercato trasferimenti · In osservazione</div><div class="market"><span><b>Marco Silva · ATT</b><small>OVR 82 · 24 anni · 🇮🇹</small></span><b>€ 18,5M</b><button class="secondary-btn" data-buy>Fai offerta</button></div><div class="market"><span><b>Leo Anders · CEN</b><small>OVR 79 · 21 anni · 🇸🇪</small></span><b>€ 12M</b><button class="secondary-btn" data-buy>Fai offerta</button></div></div></div>`}
else if(name==='ultimate'||name==='shop'){let isShop=name==='shop';html=`${backButton()}<div class="eyebrow">${isShop?'NFG Store · Premi della settimana':'La tua rosa · Stagione 01'}</div><h2 class="page-title">${isShop?'Negozio Pacchetti':'Ultimate Team'}</h2><div class="tabs"><button class="tab active" data-tab>Pacchetti</button><button class="tab" data-tab>La mia rosa</button><button class="tab" data-tab>Obiettivi</button></div><div class="card-panel"><div class="pack-zone"><div class="pack-art" id="packArt"><div class="pack-box"></div><div class="player-card" id="playerCard"><div class="rating">89 <small style="font-size:13px">ATT</small></div><div class="player-portrait"></div><div class="player-name">A. VELLI</div><div class="stats">91 VEL &nbsp; 88 TIR &nbsp; 84 TEC</div></div></div><div><div class="eyebrow">Pacchetto oro premium</div><h3 style="font:800 25px 'Barlow Condensed';margin:7px 0">3 giocatori rari</h3><div style="font-size:11px;color:#aabbb8;line-height:1.6">Una nuova stella può cambiare tutto. Scarta il pacchetto e aggiungi un campione alla tua rosa.</div><div class="info-row">✦ &nbsp; 7.500 crediti &nbsp; · &nbsp; 1 disponibile</div><button class="primary-btn" id="openPack">${isShop?'Acquista e apri':'Scarta pacchetto'}</button><button class="secondary-btn" id="discard" style="display:none;margin-left:7px">Scarta carta</button></div></div></div><div class="info-row">Crediti disponibili: <b style="color:var(--lime)">18.250</b> &nbsp; · &nbsp; Carte giocatore collezionabili</div>`}
else if(name==='settings'){html=`${backButton()}<div class="eyebrow">Personalizza la tua partita</div><h2 class="page-title">Impostazioni</h2><div class="card-panel" style="max-width:560px"><div class="sound-toggle"><span>Musica menu</span><span class="switch on" data-switch></span></div><div class="sound-toggle"><span>Effetti sonori</span><span class="switch on" data-switch></span></div><div class="sound-toggle"><span>Telecamera dinamica</span><span class="switch on" data-switch></span></div><div class="sound-toggle"><span>Difficoltà avversari</span><select style="background:#10282b;color:white;border:1px solid #ffffff30;padding:8px;border-radius:4px"><option>Accessibile</option><option>Normale</option><option>Competitiva</option></select></div><div class="info-row">Grafica ottimizzata per dispositivi mobili · Controlli touch attivi in orizzontale</div></div>`}
$('#pageContent').innerHTML=html;$('#menu').classList.add('hidden');$('#subpage').classList.remove('hidden');bindPage(name)}
function bindPage(name){document.querySelectorAll('[data-back]').forEach(b=>b.onclick=()=>{$('#subpage').classList.add('hidden');$('#menu').classList.remove('hidden')});document.querySelector('[data-start]')?.addEventListener('click',startMatch);document.querySelectorAll('.swatch').forEach(s=>s.onclick=()=>{document.querySelectorAll(`.swatch[data-team="${s.dataset.team}"]`).forEach(x=>x.classList.remove('active'));s.classList.add('active')});document.querySelectorAll('[data-switch]').forEach(s=>s.onclick=()=>s.classList.toggle('on'));document.querySelectorAll('[data-tab]').forEach(t=>t.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.remove('active'));t.classList.add('active')});document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{b.textContent='Offerta inviata ✓';b.disabled=true;playTone(480,.12)});document.querySelector('[data-form]')?.addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent.includes('Gestisci')?'Modulo 4-3-3 selezionato ✓':'Gestisci formazione'});let opened=false;$('#openPack')?.addEventListener('click',()=>{if(opened)return;opened=true;$('#packArt').classList.add('opening');playTone(430,.35,'triangle');setTimeout(()=>{$('#playerCard').classList.add('show');$('#discard').style.display='inline-block';$('#openPack').textContent='Carta aggiunta alla rosa ✓';$('#openPack').disabled=true;playTone(740,.2)},650)});$('#discard')?.addEventListener('click',()=>{let card=$('#playerCard');card.classList.remove('show');$('#discard').textContent='Scartata · +1.250 crediti';$('#discard').disabled=true;playTone(270,.15)})}
document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',()=>showPage(b.dataset.page)));
$('#resume').onclick=()=>{$('#pause').classList.remove('show');gameState='playing'};$('#quit').onclick=()=>{gameState='menu';$('#pause').classList.remove('show');$('#hud').style.display='none';$('#menu').classList.remove('hidden')};$('#toMenu').onclick=()=>{gameState='menu';$('#victory').classList.remove('show');$('#menu').classList.remove('hidden')};
$('#shoot').addEventListener('pointerdown',e=>{e.preventDefault();shootHeld=true;shotPower=0;$('#power').style.display='block'});['pointerup','pointercancel','pointerleave'].forEach(ev=>$('#shoot').addEventListener(ev,e=>{if(shootHeld)releaseShot()}));$('#pass').addEventListener('pointerdown',e=>{e.preventDefault();passBall()});$('#sprint').addEventListener('pointerdown',()=>sprinting=true);['pointerup','pointercancel','pointerleave'].forEach(ev=>$('#sprint').addEventListener(ev,()=>sprinting=false));
const stick=$('#stick'),knob=$('#knob');let stickId=null;function stickMove(e){let r=stick.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),d=Math.hypot(dx,dy),max=r.width*.33;if(d>max){dx*=max/d;dy*=max/d}joystick.x=dx/max;joystick.z=dy/max;knob.style.left=`calc(50% + ${dx}px)`;knob.style.top=`calc(50% + ${dy}px)`}stick.addEventListener('pointerdown',e=>{stickId=e.pointerId;stick.setPointerCapture(stickId);stickMove(e)});stick.addEventListener('pointermove',e=>{if(e.pointerId===stickId)stickMove(e)});function resetStick(e){if(e.pointerId!==stickId)return;stickId=null;joystick.x=joystick.z=0;knob.style.left='50%';knob.style.top='50%'}stick.addEventListener('pointerup',resetStick);stick.addEventListener('pointercancel',resetStick);
document.addEventListener('contextmenu',e=>e.preventDefault());
</script></body></html>

