.topbar{position:absolute;top:22px;left:26px;display:flex;align-items:center;gap:12px;padding:10px 16px;border:1px solid #ffffff24;background:#071b20d9;backdrop-filter:blur(14px);border-radius:8px;box-shadow:0 12px 40px #0005}
.touch-controls{position:absolute;inset:auto 0 20px;display:none;align-items:end;justify-content:space-between;padding:0 26px;pointer-events:none}
.stick-wrap{width:128px;height:128px;border-radius:50%;border:1px solid #ffffff55;background:#071a1e66;position:relative;pointer-events:auto;touch-action:none}
.actions{display:flex;align-items:end;gap:12px;pointer-events:auto}
.act{width:69px;height:69px;border-radius:50%;background:#09252bd9;border:1px solid #ffffff62;box-shadow:0 8px 20px #0007;display:flex;align-items:center;justify-content:center;flex-direction:column;gap:1px;font:800 11px 'Barlow Condensed';letter-spacing:.5px;touch-action:none}

@media (max-width:760px){.menu-layout{grid-template-columns:1fr;gap:16px}
.topbar{left:10px;top:10px;gap:8px;padding:8px 10px}
.touch-controls{display:flex;bottom:max(15px,env(safe-area-inset-bottom));padding:0 15px}
.stick-wrap{width:106px;height:106px}
.actions{gap:8px}
.act{width:58px;height:58px;font-size:9px}

@media (orientation:portrait){.hint:after{content:' • RUOTA IL DISPOSITIVO';color:var(--lime)}
.touch-controls{bottom:12px}
@media (max-width:760px) and (orientation:landscape){.touch-controls{bottom:max(8px,env(safe-area-inset-bottom));padding:0 12px}
.stick-wrap{width:78px;height:78px}
.actions{gap:6px}
.act{width:48px;height:48px;font-size:8px}
.topbar{gap:6px;padding:6px 8px}

